-- 95 Equaliser: the club follows its music. The LED wall is the mix's
-- spectrum (Audio.get_spectrum), the lights the lows, mids and highs, the
-- floor flashes on the bass and the crowd changes moves on each beat. A..K
-- play a saw lead (Audio.synth), which the wall shows too. Generated by
-- tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/95-equaliser.scene"
local COLS, ROWS = 16, 10
local DANCERS, FLOOR, KEYS = 11, 10, 8
local STEMS = { "sounds/nd_bass.wav", "sounds/nd_drums.wav", "sounds/nd_pad.wav", "sounds/nd_lead.wav" }
local NOTE_KEYS = { "A", "S", "D", "F", "G", "H", "J", "K" }
local NOTES = { 57, 60, 62, 64, 67, 69, 72, 74 }
local LIGHT = { { 1.0, 0.04, 0.45 }, { 0.03, 0.79, 1.0 }, { 1.0, 0.52, 0.05 } }

local captions = true
local e = {}
local playing = false
local t = 0
local bass_avg = 0
local beat_t = 0
local move = 0
local key_glow = {}

local function start_music()
    Audio.play_music_layers(STEMS, { 1, 1, 0.8, 0.7 }, 1.0)
    playing = true
end

function init(entity)
    for c = 0, COLS - 1 do
        for r = 0, ROWS - 1 do e["L" .. c .. "_" .. r] = Entity.find_by_name("Led" .. c .. "_" .. r) end
    end
    for i = 0, 2 do
        e["Light" .. i] = Entity.find_by_name("Light" .. i)
        e["Beam" .. i] = Entity.find_by_name("Beam" .. i)
    end
    for row = 0, 1 do
        for i = 0, FLOOR - 1 do e["T" .. row .. "_" .. i] = Entity.find_by_name("Tile" .. row .. "_" .. i) end
    end
    for d = 0, DANCERS - 1 do
        e["D" .. d] = Entity.find_by_name("Dancer" .. d)
        for k = 0, 3 do e["P" .. d .. "_" .. k] = Entity.find_by_name("Pose" .. d .. "_" .. k) end
    end
    for k = 0, KEYS - 1 do
        e["K" .. k] = Entity.find_by_name("Key" .. k)
        key_glow[k] = 0
    end
    e.Dj = Entity.find_by_name("Dj")
    start_music()
end

local function avg(s, a, b)
    local sum = 0
    for i = a, b do sum = sum + (s[i] or 0) end
    return sum / (b - a + 1)
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then
        if playing then
            Audio.stop_music()
            playing = false
        else
            start_music()
        end
    end
    t = t + dt

    -- The synth: a saw lead, a note a key.
    for i, k in ipairs(NOTE_KEYS) do
        if Input.is_key_just_pressed(k) then
            Audio.synth({ wave = "saw", note = NOTES[i], duration = 0.25, attack = 0.005, decay = 0.12,
                sustain = 0.5, release = 0.35, volume = 0.35, bus = "sfx" })
            key_glow[i - 1] = 1
        end
    end
    for k = 0, KEYS - 1 do
        key_glow[k] = math.max(0, key_glow[k] - dt * 3)
        local g = key_glow[k]
        Sprite.set_color(e["K" .. k], 0.85 + g * 0.15, 0.85 + g * 0.6, 0.9 + g * 1.5, 1)
    end

    -- The wall: sixteen bands, ten cells each, green to red as they climb.
    local s = Audio.get_spectrum(COLS)
    for c = 0, COLS - 1 do
        local lit = (s[c + 1] or 0) * ROWS
        for r = 0, ROWS - 1 do
            local f = r / (ROWS - 1)
            local on = lit > r and 1 or 0.06
            Sprite.set_color(e["L" .. c .. "_" .. r], 0.1 + 1.6 * f, 1.4 - 1.2 * f, 0.25 * (1 - f), on)
        end
    end

    -- The lights: lows, mids and highs.
    local bands = { avg(s, 1, 4), avg(s, 6, 10), avg(s, 12, 16) }
    for i = 0, 2 do
        local v = math.max(0, bands[i + 1] - 0.25) * 1.6
        Lighting.set_intensity(e["Light" .. i], 0.2 + v * 1.6)
        local c = LIGHT[i + 1]
        Sprite.set_color(e["Beam" .. i], c[1], c[2], c[3], 0.15 + v * 0.8)
    end

    -- A beat: the bass jumping above its recent average.
    local bass = bands[1]
    bass_avg = bass_avg + (bass - bass_avg) * math.min(1, dt * 2)
    beat_t = beat_t - dt
    if bass > bass_avg + 0.08 and beat_t <= 0 then
        beat_t = 0.25
        move = move + 1
    end
    local flash = math.max(0, beat_t) * 4
    for row = 0, 1 do
        for i = 0, FLOOR - 1 do
            local hue = (i + row + move) % 3 + 1
            local c = LIGHT[hue]
            local k = 0.18 + flash * 0.9 * (((i + row + move) % 2 == 0) and 1 or 0.35)
            Sprite.set_color(e["T" .. row .. "_" .. i], c[1] * k, c[2] * k, c[3] * k, 1)
        end
    end

    -- The crowd bobs with the loudness and changes moves on the beat.
    local level = Audio.get_level()
    for d = 0, DANCERS - 1 do
        local bob = math.abs(math.sin(t * 4 + d)) * (6 + level * 40)
        local x, _ = Transform.get_position(e["D" .. d])
        Transform.set_position(e["D" .. d], x, -255 - (d % 3) * 14 + bob)
        local pose = (d + move) % 4
        for k = 0, 3 do Sprite.set_color(e["P" .. d .. "_" .. k], 1, 1, 1, k == pose and 1 or 0) end
    end
    Transform.set_rotation(e.Dj, math.sin(t * 3) * 0.05 * (1 + level * 4))
end
